import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { resolve } from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";

import * as launcher from "./run-ackplane.mjs";

const { parseEnvFile, resolveEnv } = launcher;
const launcherPath = fileURLToPath(
  new URL("./run-ackplane.mjs", import.meta.url),
);
const cliCwd = fileURLToPath(new URL("../crates/", import.meta.url));
const fixtureEnv = {
  ACKPLANE_PORT: "9999",
  ACKPLANE_EMPTY: "",
  ACKPLANE_SECRET: "fixture-env-secret",
};

function runCli(args, result = { status: 0 }, throwError = false) {
  const fixture = `
    import childProcess from "node:child_process";
    import fs from "node:fs";
    import { syncBuiltinESMExports } from "node:module";
    import { resolve } from "node:path";
    import { pathToFileURL } from "node:url";

    process.env = ${JSON.stringify(fixtureEnv)};
    const readFile = fs.readFileSync;
    fs.existsSync = () => true;
    fs.readFileSync = (path, ...options) => {
      if (path === resolve(process.cwd(), ".env")) {
        return "ACKPLANE_PORT=8443\\nACKPLANE_FILE_ONLY=from-file\\nACKPLANE_EMPTY=from-file\\n";
      }
      if (typeof path === "string" && path.endsWith(".env")) {
        throw new Error("unexpected fixture environment path");
      }
      return readFile(path, ...options);
    };
    childProcess.spawnSync = (...parameters) => {
      process.stdout.write(JSON.stringify(parameters));
      const result = ${JSON.stringify(result)};
      if (${throwError}) throw new Error(result.error);
      return result;
    };
    syncBuiltinESMExports();
    await import(pathToFileURL(process.argv[1]).href);
  `;
  return spawnSync(
    process.execPath,
    ["--input-type=module", "--eval", fixture, launcherPath, ...args],
    { cwd: cliCwd, env: {}, shell: false, encoding: "utf8" },
  );
}

test("parseEnvFile reads simple KEY=VALUE lines", () => {
  const text = "ACKPLANE_PORT=8443\nACKPLANE_BRIDGE_LISTEN=127.0.0.1:18150\n";
  assert.deepEqual(parseEnvFile(text), {
    ACKPLANE_PORT: "8443",
    ACKPLANE_BRIDGE_LISTEN: "127.0.0.1:18150",
  });
});

test("parseEnvFile skips blank lines and #-comments", () => {
  const text = [
    "# a leading comment",
    "",
    "ACKPLANE_PORT=8443",
    "   ",
    "# a trailing comment",
    "ACKPLANE_VERSION=dev",
  ].join("\n");
  assert.deepEqual(parseEnvFile(text), {
    ACKPLANE_PORT: "8443",
    ACKPLANE_VERSION: "dev",
  });
});

test("parseEnvFile only splits on the first '=', so a value may contain one", () => {
  const text =
    "ACKPLANE_DATABASE_URL=postgresql://ackplane:pw@127.0.0.1:5432/ackplane?sslmode=disable";
  assert.deepEqual(parseEnvFile(text), {
    ACKPLANE_DATABASE_URL:
      "postgresql://ackplane:pw@127.0.0.1:5432/ackplane?sslmode=disable",
  });
});

test("parseEnvFile trims surrounding whitespace from both key and value", () => {
  const text = "  ACKPLANE_PORT   =   8443  \n";
  assert.deepEqual(parseEnvFile(text), { ACKPLANE_PORT: "8443" });
});

test("parseEnvFile ignores a line with no '=' rather than throwing", () => {
  const text = "ACKPLANE_PORT=8443\nnot a valid line\nACKPLANE_VERSION=dev";
  assert.deepEqual(parseEnvFile(text), {
    ACKPLANE_PORT: "8443",
    ACKPLANE_VERSION: "dev",
  });
});

test("resolveEnv lets an already-set shell variable win over .env", () => {
  const resolved = resolveEnv("no-such-file.env", { ACKPLANE_PORT: "9999" });
  assert.equal(resolved.ACKPLANE_PORT, "9999");
});

test("resolveEnv falls back to an empty object for a missing .env file", () => {
  assert.deepEqual(resolveEnv("no-such-file.env", {}), {});
});

test("run forwards register-me arguments instead of dropping enrollment flags", () => {
  // The launcher rejected register-me and dropped arguments needed by enrollment.
  assert.equal(typeof launcher.run, "function");
  const cwd = resolve("launcher workspace with spaces");
  const args = [
    "serve",
    "--state-dir",
    "state directory with spaces",
    "--approval-url",
    "https://example.invalid/approve?token=fixture&next=$(unused);*",
  ];
  const env = { ACKPLANE_PORT: "9999" };
  const calls = [];
  const status = launcher.run("register-me", args, {
    cwd,
    env,
    platform: "linux",
    exists: () => true,
    spawn: (...parameters) => {
      calls.push(parameters);
      return { status: 0 };
    },
  });
  assert.equal(status, 0);
  assert.deepEqual(calls, [
    [
      resolve(cwd, "target/release/register-me"),
      args,
      {
        cwd,
        env,
        shell: false,
        stdio: "inherit",
      },
    ],
  ]);
  assert.equal(calls[0][1], args);
});

for (const [selector, binary, packageName] of [
  ["bridge", "ackplane-bridge", "ackplane-bridge"],
  ["server", "ackplane-server", "ackplane-server"],
  ["register-me", "register-me", "ackplane-server"],
  ["supervisor", "ackplane-supervisor", "ackplane-supervisor"],
]) {
  for (const platform of ["linux", "win32"]) {
    test(`run maps ${selector} on ${platform} without a shell`, (context) => {
      const cwd = resolve("launcher workspace with spaces");
      const suffix = platform === "win32" ? ".exe" : "";
      const path = resolve(cwd, "target", "release", `${binary}${suffix}`);
      const args = Object.freeze([
        "--unknown-child-flag",
        "path with spaces",
        "",
        "--",
        "$HOME",
        "%USERPROFILE%",
        '"quoted value"',
        "'single quotes'",
        "$(not-executed); & | < > * ? `not-executed`",
        "line\nbreak",
      ]);
      const exists = context.mock.fn(() => true);
      const spawn = context.mock.fn(() => ({ status: 0 }));
      assert.equal(
        launcher.run(selector, args, {
          cwd,
          env: {},
          platform,
          exists,
          spawn,
        }),
        0,
      );
      assert.deepEqual(
        exists.mock.calls.map((call) => call.arguments),
        [[path]],
      );
      assert.equal(spawn.mock.callCount(), 1);
      assert.deepEqual(spawn.mock.calls[0].arguments, [
        path,
        args,
        {
          cwd,
          env: {},
          shell: false,
          stdio: "inherit",
        },
      ]);
      assert.equal(spawn.mock.calls[0].arguments[1], args);
    });
  }

  test(`run names the correct Cargo package and bin for missing ${selector}`, (context) => {
    const cwd = resolve("launcher workspace with spaces");
    const path = resolve(cwd, "target", "release", `${binary}.exe`);
    const spawn = context.mock.fn();
    assert.throws(
      () =>
        launcher.run(selector, ["fixture-approval-secret"], {
          cwd,
          env: fixtureEnv,
          platform: "win32",
          exists: () => false,
          spawn,
        }),
      {
        message: `${path} does not exist -- build it first: cargo build --release -p ${packageName} --bin ${binary}`,
      },
    );
    assert.equal(spawn.mock.callCount(), 0);
  });
}

test("run defaults to no arguments without adding enrollment or serve commands", (context) => {
  const spawn = context.mock.fn(() => ({ status: 0 }));
  assert.equal(
    launcher.run("register-me", undefined, {
      cwd: resolve("launcher workspace with spaces"),
      env: {},
      exists: () => true,
      spawn,
    }),
    0,
  );
  assert.deepEqual(spawn.mock.calls[0].arguments[1], []);
});

test("run rejects unknown and inherited selectors before filesystem or process calls", (context) => {
  const exists = context.mock.fn();
  const spawn = context.mock.fn();
  for (const selector of [
    undefined,
    null,
    "",
    "other",
    "__proto__",
    "constructor",
    "toString",
    42,
    Symbol("selector"),
    "fixture-approval-secret",
  ]) {
    assert.throws(() => launcher.run(selector, [], { exists, spawn }), {
      message:
        "usage: node scripts/run-ackplane.mjs <bridge|server|register-me|supervisor> [args...]",
    });
  }
  assert.equal(exists.mock.callCount(), 0);
  assert.equal(spawn.mock.callCount(), 0);
});

test("run rejects malformed argument arrays before filesystem or process calls", (context) => {
  const exists = context.mock.fn();
  const spawn = context.mock.fn();
  for (const args of [
    null,
    "--flag fixture-approval-secret",
    {},
    [42],
    [null],
    [undefined],
    ["fixture-approval-secret\0"],
    Array(1),
  ]) {
    assert.throws(() => launcher.run("supervisor", args, { exists, spawn }), {
      message: "arguments must be an array of strings without NUL bytes",
    });
  }
  assert.equal(exists.mock.callCount(), 0);
  assert.equal(spawn.mock.callCount(), 0);
});

test("run preserves exit statuses and fails on signals or absent status without changing process.exitCode", () => {
  const exitCode = process.exitCode;
  for (const [result, expected] of [
    [{ status: 0 }, 0],
    [{ status: 23 }, 23],
    [{ status: null, signal: "SIGTERM" }, 1],
    [{ status: 0, signal: "SIGINT" }, 1],
    [{ status: null }, 1],
    [{}, 1],
  ]) {
    assert.equal(
      launcher.run("server", [], {
        cwd: resolve("launcher workspace with spaces"),
        env: {},
        exists: () => true,
        spawn: () => result,
      }),
      expected,
    );
  }
  assert.equal(process.exitCode, exitCode);
});

test("CLI forwards exact trailing arguments and merges the caller workspace .env under shell values", () => {
  // main previously discarded trailing arguments, so enrollment options never arrived.
  const args = [
    "request",
    "--state-dir",
    "a state directory",
    "--approval-url",
    "https://example.invalid/approve?token=fixture-approval-secret&next=$(unused);*",
    "",
    "--",
    '"quoted"',
    "%USERPROFILE%",
  ];
  const result = runCli(["register-me", ...args]);
  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.stderr, "");
  const suffix = process.platform === "win32" ? ".exe" : "";
  assert.deepEqual(JSON.parse(result.stdout), [
    resolve(cliCwd, "target", "release", `register-me${suffix}`),
    args,
    {
      cwd: resolve(cliCwd),
      env: { ACKPLANE_FILE_ONLY: "from-file", ...fixtureEnv },
      shell: false,
      stdio: "inherit",
    },
  ]);
});

test("CLI does not invent arguments or start serve implicitly", () => {
  const result = runCli(["register-me"]);
  assert.equal(result.status, 0, result.stderr);
  assert.deepEqual(JSON.parse(result.stdout)[1], []);
});

for (const throwError of [false, true]) {
  test(`CLI makes ${throwError ? "thrown" : "returned"} child errors opaque and exits nonzero`, () => {
    const result = runCli(
      ["supervisor", "fixture-approval-secret"],
      {
        status: 0,
        error:
          "fixture-child-secret fixture-approval-secret fixture-env-secret",
      },
      throwError,
    );
    assert.equal(result.status, 1);
    assert.equal(
      result.stderr,
      "run-ackplane: could not start ackplane-supervisor\n",
    );
    assert.doesNotMatch(result.stderr, /fixture-(child|approval|env)-secret/);
  });
}

test("CLI refuses missing or unknown selectors without invoking the child or echoing input", () => {
  for (const args of [
    [],
    ["fixture-approval-secret"],
    ["__proto__"],
    ["constructor"],
  ]) {
    const result = runCli(args);
    assert.equal(result.status, 1);
    assert.equal(result.stdout, "");
    assert.equal(
      result.stderr,
      "run-ackplane: usage: node scripts/run-ackplane.mjs <bridge|server|register-me|supervisor> [args...]\n",
    );
  }
});

for (const [label, result, expected] of [
  ["nonzero status", { status: 23 }, 23],
  ["signal", { status: null, signal: "SIGTERM" }, 1],
  ["absent status", { status: null }, 1],
]) {
  test(`CLI exits correctly for a child ${label}`, () => {
    const actual = runCli(["bridge"], result);
    assert.equal(actual.status, expected, actual.stderr);
    assert.equal(actual.stderr, "");
  });
}
